import sys
from collections import deque

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        m = int(next(iterator))
        s = int(next(iterator))
    except StopIteration:
        return

    adj = [[] for _ in range(n + 1)]
    rev_adj = [[] for _ in range(n + 1)]

    for _ in range(m):
        u = int(next(iterator))
        v = int(next(iterator))
        adj[u].append(v)
        rev_adj[v].append(u)

    def bfs(start_node, graph):
        visited = [False] * (n + 1)
        q = deque([start_node])
        visited[start_node] = True
        while q:
            u = q.popleft()
            for v in graph[u]:
                if not visited[v]:
                    visited[v] = True
                    q.append(v)
        return visited

    forward_visited = bfs(s, adj)
    backward_visited = bfs(s, rev_adj)

    scc_count = 0
    in_degree = [0] * (n + 1)
    visited_scc = [False] * (n + 1)
    scc_id = [-1] * (n + 1)

    stack = []
    low = [0] * (n + 1)
    disc = [0] * (n + 1)
    timer = [0]
    on_stack = [False] * (n + 1)

    def dfs_tarjan(u):
        nonlocal scc_count
        stack.append(u)
        on_stack[u] = True
        disc[u] = low[u] = timer[0]
        timer[0] += 1

        for v in adj[u]:
            if disc[v] == 0:
                dfs_tarjan(v)
                low[u] = min(low[u], low[v])
            elif on_stack[v]:
                low[u] = min(low[u], disc[v])

        if low[u] == disc[u]:
            while True:
                v = stack.pop()
                on_stack[v] = False
                scc_id[v] = scc_count
                if v == u:
                    break
            scc_count += 1

    for i in range(1, n + 1):
        if disc[i] == 0:
            dfs_tarjan(i)

    scc_in_degree = [0] * scc_count
    scc_edges = set()

    for u in range(1, n + 1):
        for v in adj[u]:
            if scc_id[u] != scc_id[v]:
                if (scc_id[u], scc_id[v]) not in scc_edges:
                    scc_edges.add((scc_id[u], scc_id[v]))
                    scc_in_degree[scc_id[v]] += 1

    root_scc = scc_id[s]

    unreachable_from_root = 0
    for i in range(scc_count):
        if i == root_scc:
            continue
        if scc_in_degree[i] == 0:
            unreachable_from_root += 1

    print(unreachable_from_root)

if __name__ == "__main__":
    main()
